import 'package:flutter/material.dart';
import 'services.dart';
import 'theme.dart';

class CresaBotSheet extends StatefulWidget { const CresaBotSheet({super.key, required this.api, required this.token}); final CresaApi api; final String token; @override State<CresaBotSheet> createState() => _CresaBotSheetState(); }
class _CresaBotSheetState extends State<CresaBotSheet> { final prompt = TextEditingController(); final messages = <({bool user, String text})>[]; bool busy = false; Future<void> ask() async { if (prompt.text.trim().isEmpty || busy) return; final value = prompt.text.trim(); setState(() { messages.add((user: true, text: value)); prompt.clear(); busy = true; }); final result = await widget.api.askBot(widget.token, value); if (!mounted) return; setState(() { busy = false; messages.add((user: false, text: result.ok ? result.data! : result.error!)); }); } @override Widget build(BuildContext context) => SafeArea(child: SizedBox(height: MediaQuery.sizeOf(context).height * .82, child: Column(children: [Padding(padding: const EdgeInsets.fromLTRB(18, 4, 18, 12), child: Row(children: [Container(width: 36, height: 36, decoration: BoxDecoration(color: const Color(0xffe5f0ff), borderRadius: BorderRadius.circular(11)), child: const Icon(Icons.auto_awesome_rounded, color: CresaTheme.blue)), const SizedBox(width: 10), const Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('CresaBot', style: TextStyle(fontSize: 16, fontWeight: FontWeight.w800, color: CresaTheme.ink)), Text('Academic study assistant', style: TextStyle(fontSize: 10, color: CresaTheme.muted))])])), Expanded(child: messages.isEmpty ? const Center(child: Text('Ask about your studies, a concept, or a resource.', style: TextStyle(color: CresaTheme.muted))) : ListView.builder(padding: const EdgeInsets.all(18), itemCount: messages.length, itemBuilder: (_, index) { final message = messages[index]; return Align(alignment: message.user ? Alignment.centerRight : Alignment.centerLeft, child: Container(constraints: const BoxConstraints(maxWidth: 310), padding: const EdgeInsets.all(12), margin: const EdgeInsets.only(bottom: 9), decoration: BoxDecoration(color: message.user ? const Color(0xff3477e7) : const Color(0xfff0f5fd), borderRadius: BorderRadius.circular(14)), child: Text(message.text, style: TextStyle(color: message.user ? Colors.white : CresaTheme.ink, height: 1.4))); } }), if (busy) const Padding(padding: EdgeInsets.only(bottom: 6), child: Text('CresaBot is thinking...', style: TextStyle(color: CresaTheme.muted, fontSize: 11))), Padding(padding: EdgeInsets.fromLTRB(14, 6, 14, 12), child: Row(crossAxisAlignment: CrossAxisAlignment.end, children: [Expanded(child: TextField(controller: prompt, minLines: 1, maxLines: 4, onSubmitted: (_) => ask(), decoration: const InputDecoration(hintText: 'Ask CresaBot...'))), const SizedBox(width: 8), IconButton.filled(onPressed: busy ? null : ask, icon: const Icon(Icons.send_rounded))]))])); }
